export default function f({ mailbox, messageId }) {
  if (!["INBOX_1", "INBOX_2"].includes(mailbox) || !messageId)
    throw Error("Enter original inbox and message ID");
  return {
    mailbox,
    events: [
      {
        messageId,
        threadId: "",
        historyId: null,
        labelIds: [],
        subject: "",
        sender: "",
        to: "",
        messageTimestamp: "",
      },
    ],
  };
}

