export default async function f({ events, previous, mailbox, acknowledge, resolution }, ctx) {
  if (!/^[\w-]{1,80}$/.test(mailbox)) throw Error("Configure a distinct mailbox namespace");
  const i = previous?.index ?? 0;
  if (i >= events.length) return { state: { index: i }, more: false, messageId: "-", mailbox };
  const e = events[i];
  if (!e?.messageId) throw Error("Missing Gmail message ID");
  const key = "campaign-reply:" + mailbox + ":" + e.messageId,
    s = await ctx.state.get(key);
  if (s?.phase === "done")
    return f({ events, previous: { index: i + 1 }, mailbox, acknowledge, resolution }, ctx);
  if (s?.phase === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending deal " + key);
    await ctx.state.set(key, resolution === "confirmed" ? { phase: "done" } : null);
    return f({ events, previous, mailbox, acknowledge: "", resolution: "" }, ctx);
  }
  return { state: { index: i + 1 }, more: true, messageId: e.messageId, mailbox };
}

