export default function f({ id, from, body }) {
  const match = from.match(/<?([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})>?/i);
  if (!match) throw Error("Could not identify sender");
  const lines = [];
  for (const line of body.split(/\r?\n/)) {
    if (
      /^On .+wrote:\s*$/i.test(line.trim()) ||
      /^\s*>/.test(line) ||
      /^[- ]{2,}Original Message[- ]*$/i.test(line.trim())
    )
      break;
    lines.push(line);
  }
  const text = lines.join("\n").trim();
  if (!text || text.length > 14800) throw Error("Reply body empty or too long");
  return { id, email: match[1].toLowerCase(), text };
}

