export default function f({ items, cursor, email }) {
  if (cursor || items.length > 1) throw Error("Ambiguous CRM email match");
  if (!items.length) return { matched: false, personId: 1 };
  const p = items[0]?.item;
  if (!p?.id || !Array.isArray(p.emails) || !p.emails.some((x) => x.toLowerCase() === email))
    throw Error("CRM search did not confirm exact sender email");
  return { matched: true, personId: p.id };
}

