export default async function f(
  { raw, text, person, mailbox, messageId, acknowledge, resolution },
  ctx,
) {
  if (raw?.candidates?.[0]?.finishReason !== "STOP" || !text?.trim())
    throw Error("Incomplete classification");
  let result;
  try {
    result = JSON.parse(text.trim().replace(/^```(?:json)?\s*|\s*```$/g, ""));
  } catch {
    throw Error("Invalid classification JSON");
  }
  if (typeof result.interested !== "boolean" || typeof result.reason !== "string")
    throw Error("Invalid classification fields");
  const key = "campaign-reply:" + mailbox + ":" + messageId,
    s = await ctx.state.get(key);
  if (s?.phase === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending deal " + key);
    await ctx.state.set(key, resolution === "confirmed" ? { phase: "done" } : null);
    if (resolution === "confirmed") return { create: false, key, title: "-", personId: person.id };
  }
  if (!result.interested) {
    await ctx.state.set(key, { phase: "done" });
    return { create: false, key, title: "-", personId: person.id };
  }
  if (!person.id || !person.name) throw Error("Missing person ID or name");
  await ctx.state.set(key, { phase: "pending" });
  return { create: true, key, title: person.name + " Deal", personId: person.id };
}

