export default async function f({ key, deal, personId }, ctx) {
  const s = await ctx.state.get(key);
  if (s?.phase !== "pending" || !deal.id || deal.person_id !== personId)
    throw Error("Inspect created Pipedrive deal");
  await ctx.state.set(key, { phase: "done" });
  return { ok: true };
}
